--
-- Name: now_playing; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.now_playing (
    id boolean DEFAULT true NOT NULL,
    song_id text NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    ends_at timestamp with time zone NOT NULL,
    CONSTRAINT now_playing_check CHECK ((ends_at > started_at)),
    CONSTRAINT now_playing_id_check CHECK (id)
);

ALTER TABLE public.now_playing OWNER TO postgres;

--
-- Name: music_play(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.music_play(p_song text) RETURNS public.now_playing
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  length_ms int;
  playing public.now_playing;
begin
  select coalesce(duration_ms, 600000) into length_ms from public.songs where id = p_song;
  if not found then
    raise exception using errcode = 'P0002', message = 'No such song.';
  end if;
  insert into public.now_playing (id, song_id, started_at, ends_at)
    values (true, p_song, now(), now() + make_interval(secs => length_ms / 1000.0))
    on conflict (id) do update set song_id = excluded.song_id, started_at = excluded.started_at, ends_at = excluded.ends_at
    returning * into playing;
  return playing;
end;
$$;

ALTER FUNCTION public.music_play(p_song text) OWNER TO postgres;

