--
-- Name: songs_within_limit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.songs_within_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  most int := public.song_limit();
begin
  perform pg_advisory_xact_lock(hashtextextended('songs', 0));
  if (select count(*) from public.songs) >= most then
    raise exception using errcode = 'P0429', message = format('The library is full (%s songs). Remove one first.', most);
  end if;
  return new;
end;
$$;

ALTER FUNCTION public.songs_within_limit() OWNER TO postgres;

--
-- Name: stickies_saved(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.stickies_saved() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.version := case when new.body is distinct from old.body then old.version + 1 else old.version end;
  new.updated_at := now();
  return new;
end;
$$;

ALTER FUNCTION public.stickies_saved() OWNER TO postgres;

--
-- Name: stickies_within_limit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.stickies_within_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  most int := coalesce((select (value #>> '{}')::int from public.music_settings where name = 'sticky_limit'), 50);
begin
  perform pg_advisory_xact_lock(hashtextextended('stickies:' || new.user_id::text, 0));
  if (select count(*) from public.stickies where user_id = new.user_id) >= most then
    raise exception using errcode = 'P0429', message = format('You have %s stickies already. Close one first.', most);
  end if;
  return new;
end;
$$;

