CREATE TABLE public.soapbox_posts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    body text NOT NULL,
    kind text DEFAULT 'note'::text NOT NULL,
    place text,
    weather text,
    hidden boolean DEFAULT false NOT NULL,
    telegram_message_id bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    images jsonb DEFAULT '[]'::jsonb NOT NULL,
    media_group_id text,
    CONSTRAINT soapbox_posts_body_shape CHECK (((char_length(TRIM(BOTH FROM body)) <= 2000) AND ((char_length(TRIM(BOTH FROM body)) >= 1) OR (jsonb_array_length(images) > 0)))),
    CONSTRAINT soapbox_posts_images_shape CHECK (((jsonb_typeof(images) = 'array'::text) AND (jsonb_array_length(images) <= 10))),
    CONSTRAINT soapbox_posts_kind_check CHECK ((kind = ANY (ARRAY['note'::text, 'rant'::text])))
);

ALTER TABLE public.soapbox_posts OWNER TO postgres;

