    rating smallint,
    plays integer DEFAULT 0 NOT NULL,
    played_at timestamp with time zone,
    CONSTRAINT song_stats_plays_check CHECK ((plays >= 0)),
    CONSTRAINT song_stats_rating_check CHECK (((rating >= 1) AND (rating <= 5)))
);

ALTER TABLE public.song_stats OWNER TO postgres;

--
-- Name: songs; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.songs (
    id text NOT NULL,
    title text NOT NULL,
    artist text NOT NULL,
    album text,
    cover public.music_cover,
    track integer,
    instrumental boolean DEFAULT false NOT NULL,
    lyrics_offset integer DEFAULT 0 NOT NULL,
    lyrics_id bigint,
    duration_ms integer,
    added_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT songs_album_check CHECK (((char_length(TRIM(BOTH FROM album)) >= 1) AND (char_length(TRIM(BOTH FROM album)) <= 200))),
    CONSTRAINT songs_artist_check CHECK (((char_length(TRIM(BOTH FROM artist)) >= 1) AND (char_length(TRIM(BOTH FROM artist)) <= 200))),
    CONSTRAINT songs_duration_ms_check CHECK (((duration_ms >= 1000) AND (duration_ms <= 3600000))),
    CONSTRAINT songs_id_check CHECK ((id ~ '^[A-Za-z0-9_-]{11}$'::text)),
    CONSTRAINT songs_lyrics_id_check CHECK ((lyrics_id > 0)),
    CONSTRAINT songs_lyrics_offset_check CHECK (((lyrics_offset >= '-30000'::integer) AND (lyrics_offset <= 30000))),
    CONSTRAINT songs_title_check CHECK (((char_length(TRIM(BOTH FROM title)) >= 1) AND (char_length(TRIM(BOTH FROM title)) <= 200))),
    CONSTRAINT songs_track_check CHECK (((track >= 1) AND (track <= 99)))
);

ALTER TABLE public.songs OWNER TO postgres;

--
-- Name: stickies; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.stickies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid DEFAULT auth.uid() NOT NULL,
    body text DEFAULT ''::text NOT NULL,
    color text DEFAULT 'yellow'::text NOT NULL,
    x integer DEFAULT 60 NOT NULL,
    y integer DEFAULT 60 NOT NULL,
    width integer DEFAULT 220 NOT NULL,
    height integer DEFAULT 180 NOT NULL,
    collapsed boolean DEFAULT false NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT stickies_body_check CHECK ((char_length(body) <= 4000)),
    CONSTRAINT stickies_color_check CHECK ((color = ANY (ARRAY['yellow'::text, 'blue'::text, 'green'::text, 'pink'::text, 'purple'::text, 'gray'::text]))),
    CONSTRAINT stickies_height_check CHECK (((height >= 60) AND (height <= 900))),
    CONSTRAINT stickies_width_check CHECK (((width >= 120) AND (width <= 900))),
    CONSTRAINT stickies_x_check CHECK (((x >= 0) AND (x <= 10000))),
    CONSTRAINT stickies_y_check CHECK (((y >= 0) AND (y <= 10000)))
);

ALTER TABLE public.stickies OWNER TO postgres;

--
-- Name: todos; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.todos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid DEFAULT auth.uid() NOT NULL,
    title text NOT NULL,
    calendar text DEFAULT 'home'::text NOT NULL,
    priority integer DEFAULT 0 NOT NULL,
    due date,
    done boolean DEFAULT false NOT NULL,
    done_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    CONSTRAINT todos_calendar_check CHECK ((calendar = ANY (ARRAY['home'::text, 'work'::text]))),
    CONSTRAINT todos_due_check CHECK (((due >= '2000-01-01'::date) AND (due <= '2100-12-31'::date))),
    CONSTRAINT todos_priority_check CHECK (((priority >= 0) AND (priority <= 3))),
    CONSTRAINT todos_title_check CHECK ((((char_length(title) >= 1) AND (char_length(title) <= 200)) AND (title = btrim(title)) AND (title !~ '[[:cntrl:]]'::text)))
);

ALTER TABLE public.todos OWNER TO postgres;

